// Standard String Literal (Read-only data)
const char* literal_str = "This is constant text data.";

// String Literal stored in a modifiable array (copy)
char message[] = "Editable content.";

// Null Termination: automatically appended \0
// literal_str[27] is '\0'

// Escape Sequences
const char* special = "Use newline.\nUse tab.\tUse backslash.\\";

// Escaping double quotes within the literal
const char* quotes = "She said, \"Hello!\"";

// Adjacent string literals are automatically concatenated
const char* long_url = "https://www.example.com/api/v1/"
                       "resource?id=123";
